inline Expected<Instance> Instance::create(const InstanceDesc& desc) {
    auto messageCallback = desc.messageCallback ? std::make_shared<MessageCallback>(desc.messageCallback) : nullptr;
    const bfr_instance_desc cDesc = detail::toC(desc, nullptr, messageCallback.get());
    bfr_instance* instance = nullptr;
    if (const bfr_result result = bfr_create_instance(&cDesc, &instance); result < 0) {
        return std::unexpected(detail::failure(result));
    }
    return Instance{instance, std::move(messageCallback)};
}

inline Expected<std::vector<AdapterInfo>> Instance::adapters() const {
    std::vector<bfr_adapter_info> adaptersC;
    std::uint32_t count = 0;
    // Asked again while the list grows between the two calls.
    for (;;) {
        bfr_result result = bfr_get_adapters(instance_, &count, nullptr);
        if (result < 0) {
            return std::unexpected(detail::failure(result));
        }
        adaptersC.resize(count);
        result = bfr_get_adapters(instance_, &count, adaptersC.data());
        if (result < 0) {
            return std::unexpected(detail::failure(result));
        }
        if (result != BFR_RESULT_INCOMPLETE) {
            break;
        }
    }
    std::vector<AdapterInfo> adapters;
    adapters.reserve(count);
    for (std::uint32_t i = 0; i < count; ++i) {
        adapters.push_back(detail::fromC(adaptersC[i]));
    }
    return adapters;
}

